function registerExitHandlers(): void {
  if (exitHandlersRegistered) return;
  exitHandlersRegistered = true;

  const cleanup = async () => {
    if (!registeredSessionId) return;
    await stopSessionApiServer();
    await removeSession(registeredSessionId);
  };

  process.on("exit", () => {
    void cleanup();
  });
  process.on("SIGINT", () => {
    void cleanup().finally(() => process.exit(0));
  });
  process.on("SIGTERM", () => {
    void cleanup().finally(() => process.exit(0));
  });
}

export async function startSessionRegistration(options: {
  id: string;
  mode: SessionMode;
  status?: SessionStatus;
  details?: Record<string, unknown>;
  capabilities?: SessionCapabilities;
  api?: SessionControlEndpoint;
  health?: SetSessionHealthInput;
  cwd?: string;
  pid?: number;
  heartbeatIntervalMs?: number;
}): Promise<void> {
  if (registeredSessionId && registeredSessionId !== options.id) {
    await stopSessionApiServer();
    await removeSession(registeredSessionId);
  }

  registeredSessionId = options.id;
  const capabilities = options.capabilities ?? {
    observe: true,
    control: false,
    interact: false,
  };
  let endpoint = options.api;
  if (!endpoint) {
    try {
      endpoint = await startSessionApiServer(options.id, capabilities);
    } catch {
      endpoint = undefined;
    }
  }
  const now = new Date().toISOString();
  const session: SessionRecord = {
    id: options.id,
    pid: options.pid ?? process.pid,
    mode: options.mode,
    cwd: options.cwd ?? process.cwd(),
    started_at: now,
    last_seen: now,
    status: options.status ?? "idle",
    details: options.details,
    capabilities,
    api: endpoint,
    health: {
      state: options.health?.state ?? "ok",
      reason: options.health?.reason,
      confidence: options.health?.confidence ?? 1,
      first_seen: now,
      last_seen: now,
      evidence: options.health?.evidence,
      remediation: options.health?.remediation,
    },
  };

  await registerSession(session);

  if (heartbeatTimer) {
    clearInterval(heartbeatTimer);
  }

  const interval = options.heartbeatIntervalMs ?? DEFAULT_SESSION_HEARTBEAT_MS;
  heartbeatTimer = setInterval(() => {
    if (!registeredSessionId) return;
    void heartbeatSession(registeredSessionId);
  }, interval);

  heartbeatTimer.unref?.();
  registerExitHandlers();
}

export async function stopSessionRegistration(): Promise<void> {
  if (heartbeatTimer) {
    clearInterval(heartbeatTimer);
    heartbeatTimer = null;
  }
  await stopSessionApiServer();
  if (registeredSessionId) {
    await removeSession(registeredSessionId);
  }
  registeredSessionId = null;
}

export async function setSessionStatus(
  status: SessionStatus,
  details?: Record<string, unknown>,
): Promise<void> {
  if (!registeredSessionId) return;
  const patch: Partial<SessionRecord> = { status };
  if (details) {
    patch.details = details;
  }
  await updateSession(registeredSessionId, patch);
}

export async function updateSessionDetails(
  details: Record<string, unknown>,
): Promise<void> {
  if (!registeredSessionId) return;
  const current = await getSession(registeredSessionId);
  const mergedDetails = {
    ...(current?.details ?? {}),
    ...details,
  };
  await updateSession(registeredSessionId, { details: mergedDetails });
}

export async function setRegisteredSessionHealth(
  input: SetSessionHealthInput,
): Promise<void> {
  if (!registeredSessionId) return;
  await setSessionHealth(registeredSessionId, input);
}

export async function clearRegisteredSessionHealth(): Promise<void> {
  if (!registeredSessionId) return;
  await clearSessionHealth(registeredSessionId);
}

export function getRegisteredSessionId(): string | null {
  return registeredSessionId;
}

