  try {
    console.debug(
      `[Resume] Attempting to restore session: ${checkpoint.sessionId}`,
    );
    console.debug(
      `[Resume] Session meta: mode=${checkpoint.sessionMeta.mode}, cwd=${checkpoint.sessionMeta.cwd}`,
    );
    await startSessionRegistration({
      id: checkpoint.sessionId,
      mode: checkpoint.sessionMeta.mode as "tui" | "headless" | "noninteractive" | "scheduler" | "orchestrator",
      cwd: checkpoint.sessionMeta.cwd,
      details: checkpoint.sessionMeta.details,
      capabilities: checkpoint.sessionMeta.capabilities,
    });
    // Update the config's session ID to match the restored session
    config.setSessionId(checkpoint.sessionId);
    console.debug(
      `[Resume] Successfully restored session registration for ${checkpoint.sessionId}`,
    );
  } catch (error) {
    console.debug(
      `[Resume] Failed to restore session registration:`,
      error,
    );
  }
} else {
  console.debug(
    `[Resume] No session metadata in checkpoint, skipping session restoration`,
  );
  if (!checkpoint.sessionMeta) {
    console.debug(`[Resume] Reason: checkpoint.sessionMeta is undefined`);
  }
  if (!config) {
    console.debug(`[Resume] Reason: config is null`);
  }
}

